) AS (
  VALUES 
    (491::BIGINT, 'La materia ya es dificil pero este profesor la hace lo más comprensible. Hace muchos ejercicios, explica las veces que sea necesario y ayuda al estudiante cuando uno lo necesita. Pero si me hizo falta el que dejará a los estudiantes resolver en clase, pero entendible por la naturaleza del curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'e1b0d8d4e1177f74f6acb366db1e6db61afa6f89a87c1c6458a4afd3f7b77279'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'el profesor es muy bueno. Se toma el tiempo en clase para hacer como un lo que necesitas saber antes de ver x tema. Se le entiende muy claro, si usted hace las cosas a como el le gusta le irá bien. Lo malo, es que por ver tanta teoría no logra resolver muchos ejemplos como a uno le gustaria.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'c6acc4ebcb4ddd969588c32dc8e9c6239c96548b80795e733995a04c62dfb04a'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'en mi caso no tenía quices, solo tareas, eso ayuda mucho y el % de asistencia que el da, recomendado'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'be03cec8a06cda6bf29551eba4258e431f33b00add2bb1f7293092c22ed45dbf'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Excelente profesor. Le encantan los temas. Explica súper claro siempre en la pizarra, paso a paso, con colores y dibujos AMO. Deja tareas (grupales) en lugar de quices. Hace la clase divertida aunque a veeces se pasa con los chistes. Califica lo justo, puede que dé puntos extras.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'fdb51ef77d19718b508ca755ec4a05ba458e32311beca7d32153293cabab8e9d'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Muy buen profe explica muy claro aunque algunos les aburre sus momentos donde cuenta historia a mi me parece genial ya que ayuda al por qué y de dónde salen las cosas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '7f738a4ad593748725900bc8bd37ffd727e433912a79ae4747fae1b16221e8bf'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'La cabra'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'be00ef3487628a8c9dca0005b65a7b7cf39aa100531f7ce26bb5e9c683f96f32'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'El GOAT, explica muy claramente si no le quedo claro algo lo vuelve a explicar muy bien no tenga miedo de preguntar, califica justo pero también considera que tan comprometido a estado el estudiante con el curso y le brinda ayuda. Si lo elige no se va a arrepentir'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '05beb6bc739eae9110b7f310660a7bd7e1954f447cbe4f3f5891a7edd7699280'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '548417808c2c6a5ad3c12023a2c99b511a4dcb71dd36f1453ad4d5fa27f85795'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Es muy buen profesor, explica todos los temas con mucha claridad. Se nota que le gusta lo que hace. Ayuda al estudiante si este lo necesita y ha mostrado interés. Hace comentarios graciosos y chistes, hacen la clase amena y no tan monótona. Vale la pena llevar el curso con él, no se va a arrepentir.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '26be614f76e9aeb828590f72c13075ccb5bc26a513a8f7fd5645c3955d67e929'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'No he visto persona más racista, clasista, xenófoba, etc de adjetivos, en mi vida. Este profesor es S+ Tier. Explica demasiado bien los temas y da tips y métodos extra para que a uno le sea más fácil, califica de manera justa y nota el esfuerzo del estudiante. Meta con él, no lo piense.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '93373a2d6e08f92c9183019528b0cc4eb8c6f220c9c88e2f21277704f8ca1a60'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, '2TareasAntesDeCadaParcial,NoQuices,SeSalvanDeHacerLasTareasDel P*u*o Coordinador. El curso se pasa con los 2 primeros parciales, enElTercero maman pic*ha comoNuncaLoVanAHacer. Anddy comoProfeyComo persona es excelente. El maeAyudaBastanteYsiUstedDemuestra interés júreloQueElMaeLotendráPresente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c54335dc145a55905ecfc58ab3d8ccfaf2897bce508eba6161d79e3bb153147d'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'El mae explica super bien, deja bastantes tareas y no hace quices. Las clases son entretenidas y suele soltar comentarios funables, ahí usted o lo ignora o se ríe con el jajajs. Pero fuera de vara, este curso puede ser durillo y por eso yo lo recomiendo con el, no se desperdicia tiempo, entrele'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cbd9bdb2ddaf520d4c4cc328846f354ee847ce2860ee48491d759694a11f5ebf'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Increíble profesor. Sus clases son dinámicas y muy cómicas. Hace ejercicios más duros que los exámenes entonces eso ayudar a prepararse mejor. Ayuda mucho si uno le pone, pero si uno se pone de NPC en el curso no espere mucho XD el mejor profe de la escuela que me ha dado un curso'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, '92678cdef46d8fc854bb4b255fd07f5995e5d71a23078610322de7fc4968370f'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'El profe ayuda muchísimo y da crédito extra. Mientras usted preste atención va a ser el mejor profe. Explica mejor que cualquiera. Hace comentarios que cree que son "super cancelables" pero solo hay que ignorarlo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'cc3c4bf246ce3a32723f0a6b2784367549d432a56c8bf8e403125cbf119f8754'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'De los mejores profes del tec, hace clases entretenidas con sus métodos de enseñanza que pueden ser hasta cierto punto histriónicos y a la vez con la capacidad de desarrollar los temas de una forma super clara. Tiene un humor negro que es solo apto para personas de buen gusto(no cristalitos)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'bf3ae296f2adda86b5a7649f5a2458ae3fd9425516d0c70e621b7e7b3183a513'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, '11/10, excelente profesor, le sabe demasiado y tiene buenas prácticas pedagógicas, el curso se hace entretenido y no pesado, es vital apuntar todo lo que se hace en clase, aunque en algunos semestres él brinda los apuntes, no hay perdida con él, tercer curso y sigue siendo la mejor opción!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5804c173c973f687a24df7b650bf4c0785983a32a15a4499e30804a0587c34a8'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'El man es super claro con la materia. Ayuda bastante en cuanto a evaluación. Hace comentarios muy cancelables, pero divertidos. No hace quizzes. Deja clases grabadas con apuntes. Es muy justo. Tareas grupales (Se puede cambiar de grupo en cada tarea).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'aa364c450f0d24d9c052194c027e24c06cb8944fb9565760f05da4dfc37e59f2'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Como profe y persona, es excelente. Califica de forma justa, ayuda un montón y es empático con los estudiantes. Tiene humor negro, pero uno se termina acostumbrando. Súper importante tener un buen grupo para las tareas, que son el 15% y son difíciles. Absolute GOAT.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '184b57504ad8cc114d96246b3fa2bcdd038405b26acf146abc33b175ec06569a'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Excelente profe, es el segundo curso que llevo con él, el primero fue CDI, y sigue sin decepcionar. Explica sumamente bien, da muchos ejemplos de los temas, siempre dispuesto a ayudar a sus estudiantes, no hace quices, únicamente tareas que suelen ser grupales. Defecto: Humor algo rancio.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '833ed4f9b2c295c7923d191e5981db694d30ea77f8a5cf05a4d6052384b43738'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'El GOAT de la escuela de mate. Explica los temas bastante bien, le ayuda de muchas formas y califica justamente. Si nunca ha llevado con él, puede que le tome tiempo adaptarse a su forma de ser, pero en realidad, cae muy bien. Superior es un curso rudo, pero con él, se hace más llevadero el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b3dec61553a7d3e040b22e8ab043301994f40ef30beb9101236fa86630b335fb'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Un profesor que al inicio cuesta adaptarse a la forma de él, pero cuando se logra, sus clases se vuelven dinámicas y entretenidas. Muy buen sentido del humor y un profesor bastante carismático y considerado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'a1ae23d4f81a99f76b90532b2af2a5ba03a5d42c1bdd3a64436096410045ce60'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Explica de forma muy clara la materia, resuelve dudas, organiza muy bien sus clases. Él lo prepara increíble para los exámenes, pero uno tiene que poner de su parte. Si puede, matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-11-24T00:00:00+00:00'::TIMESTAMPTZ, '3dd27590fa3b5a3998dd23a05ce560b7970ff393d3c36c52f54da7062299c068'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'El GOAT de la escuela de mate'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-11-22T00:00:00+00:00'::TIMESTAMPTZ, '310376c96d406b8a356a8e18a560950a36f1d07d49e212b5c89a0a664a7667fa'::TEXT, ARRAY[923]::BIGINT[]),
    (491::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-21T00:00:00+00:00'::TIMESTAMPTZ, '7024bde9a78dfb19857854de8eb4bef3e6f733525e5a94c68d5a9047daa8249f'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Tiene humor otaku, pero es un genio para dar clases, más si son asistidas. Deja mucho material de apoyo, además de poner ejercicios en las tareas más complicados que en los exámenes, lo cual ayuda a que los exámenes se hagan fácil, da nota por asistencia y es una persona muy amable y empática.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'f82cf51d09d964f3fecad0145b7420cb27e134cbcb02bff3568662951af766dc'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'El único problema? El profe tiene su sentido del humor. Si te logras adaptar, entonces vas a poder recibir clases con el mejor profe de la escuela de mate. Es buena nota y califica bastante bien, a veces las evaluaciones son difíciles pero son cosas que el te prepara para poder hacer.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'ffd84b67e44d61b2d2ac6b064df5497ff2778455bd158dc881eebfb961436719'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Es buen profe, al principio puede ser algo confuso porque satura de información pero al final todo lo que enseña es útil. Califica duro pero eso hace que uno preste más atención a los detalles. Si usted se esfuerza va a pasar el curso. Es muy buena gente y tiene humor raro, tqm anddy'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-25T00:00:00+00:00'::TIMESTAMPTZ, '06bc2469a9e3b51c57c47f906eb582a1a75c3629a67512d36a59231a9c7b110a'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Muy buena organización y claridad. Muy entretenido y explica muy bien. Resuelve dudas. Manda tareas grupales difíciles y los exámenes son más complicados que los de cátedra. Dice cosas divertidas o no, depende de que considere divertido. Manda videos o lecturas largas. Clase recomendada 100%'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'ac09d4c79ddde1944140d12009fe2e0c06b7c3b3cdf220b48076cee2df0e1827'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Excelente profesor, algo funable pero es tan buen profe que es lo de menos. Brinda mucho apoyo. Las clases excelentes y además que deja videos fines de semana. Su forma de dar el curso lo obliga a uno a esforzarse mucho más. Si pueden llevar con Anddy no lo duden, es el mejor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-07-06T00:00:00+00:00'::TIMESTAMPTZ, '4e2c84290e9fd0f5c52ace187b7cd27a45d5e3fb864c186688bb1adee52ba6f4'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mae es una teja, no lo duden, solo pongan de su parte y estudien bastante por que es un curso exigente, el profe es un pichudo para explicar, el mae se maneja ese ego por que sabe que es el mejor profe Mate así que no duden matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'a1556f982e0436713818a30e9b2c19f214869c14199f9b5e1e4baf93950c4b68'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Este troll está loco pero es excelente profe. Hace comentarios extremadamente funables pero explica super bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '0474e9b06552e5ab30692309be90c6ff259c41e0b84ab33decfc25603704239c'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Explica de muy buena forma y es muy claro, además, hace demasiados ejemplos de cada tema. De vez en cuando suelta una burrada, lo que hace que la clase sea amena. Uno de los mejores profes que he tenido. Nada más ponerle y demostrar interés desde un inicio, y se pasa cómodo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bb60ac06312ae55f3491c4a2e6fd1fdab24014af1d86665527719e21dfd3a820'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'El mejor profe de CDI, si pueden matricularlo con el no lo duden. Explica increíble y si usted tiene dudas siempre lo va a ayudar y atenderle las dudas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bda0ea9f852b719d5c6111d1f3f4b722aa5e5cd8fc9cfd8ba3f979d08baf155e'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Un profesor muy bueno, tiene una personalidad única y la evaluación que hace ayuda a que no sea tan rudo pasar. Volvería a matricular con el'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd3442716776a3ba925ca4954ae91ee4353da7d70e308ead2f9793f31899234af'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Muy buen profe, explica super bien y literalmente te prepara para cualquier ejercicio, ya sea lo más fácil o lo más complejo. No se deje llevar por la primera impresión, pareciera que es mala gente pero es el mejor profe que va tener, tiene un humor pesadito pero nada personal, ily andy'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'e3076b529f3bfa313aeb651d262d9384e0d8c2def9124a4e879965391c3723be'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '164d3e911822fcdb940d486965ef351da36d98e53112eaca044a49c1a9e80a73'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Es el mejor profe que de verdad puede haber, si usted está dispuesto a esforzarse y dar lo mejor de usted, definitivamente matricule cuando pueda con Anddy, si usted no aguanta nada mejor ni matricule y no pierda el tiempo, él valora mucho el esfuerzo y no avanza hasta que todos entiendan todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f6666e85e88ba47154d4a7ce941965d0c51eb786a64b6e768267dc1aacf0efa3'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es muy bueno explicando, pero tiene un humor pesadito, califica duro y te presiona bastante durante el curso, a veces pone puntos extra a las calificaciones y eso es una salvada, pero es un curso que se sufre mucho, lo recomiendo, pero no se tomen nada personal y practiquen todas las semanas'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-03-06T00:00:00+00:00'::TIMESTAMPTZ, '41c0eb0fd796ca112bacc317232c1ad0fd075c28bc4ecfa82877a1407fd224e3'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profe que existe del curso, literal no hay nadie mejor y lo sabe. Muy muy recomendado, te prepara al 100 para el examen con ejercicios duros, ponga de su parte y de fijo va a pasar con Andy, 20/10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2025-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'a32f38f8bd3f74537d4492a1a81f02f7dd6675ae29205157e56ed9c0cab3ab7e'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Metodología excelente, ejemplos profundos y claros, muchos ejercicios de práctica y explicaciones detalladas. 10/10, si tiene la opción de matricular con él no lo piense. En verano particularmente hace exámenes y tareas en grupo y ayuda con un 15% por asistencia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2025-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c2a6e8f886d111d6b45af18aa379ed2d82bc8613b765976ec9e3f9a07acee43c'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'El mejor profe que he tenido incluso mejor que Marcial. Eso sí si espera un profe con el que se pase fácil, está mam… él lo prepara increíble pero tiene que poner de su parte sino está frito. Busca siempre ayudar de todas las maneras posibles si le pone y no es solo un NPC en el grupo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-01-27T00:00:00+00:00'::TIMESTAMPTZ, '388de757ea21fb64c665cea09d3b7139af8fefc656407906a13b7c65649fd1a3'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Es la vrga literalmente, explica bien, da un porcentaje por asistencia y hace ejercicios dificiles, sí, pero ayudan a poder resolver cualquier ejercicio. Es el tercer curso que llevo con él y como siempre satisfecho con los resultados. "Soy pichudisimo"-Anddy Alvarado Solano (siempre).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-24T00:00:00+00:00'::TIMESTAMPTZ, '6539d3533184841c1e1f1151249b65ca0c04a4259cb759ac7bd4060e19d91d3b'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'Excelente profesor, explica todo muy bien, matricule con él se lo recomiendo 100%, de la escuela de Mate el mejor, los ejercicios que hace en clases son suficientes para resolver cualquier otro ejercicio con mayor o menor dificultad, super feliz de haber llevado con el.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-24T00:00:00+00:00'::TIMESTAMPTZ, '39cc0302de642ef6049b0539551b8af3d7d153e6f8b4eb8a9018853f669ad43b'::TEXT, ARRAY[1049]::BIGINT[]),
    (491::BIGINT, 'Explica súper bien, ayuda mucho con tareas extras. Es un poco pasado cómicamente, pero no le de importancia, nada personal.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '52417bcc0dd99334ec0106b30e979fe2de76a64fa0de8d3749bcb80a5eeadf82'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Muy buen profesor, explica bastante bien, si puede matricular con él se lo recomiendo 100%, deja varias tareas, que son complicadas pero son en grupos y deja videos para ver extra clase de la materia, esto por que explica bastante cada tema, si le dedica el suficiente tiempo se pasa bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '100eee7c45129d68ac925d0c5eb94596ec5b9d21cdfc3a84674cf152009272b9'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es un excelente profesor, si tiene la oportunidad de matricular con él, no lo piense, hágalo!!. Deja tareas duras pero son en grupo. Tiene un humor que no es para cualquiera pero en general es muy buena gente y siempre esta dispuesto a ayudar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '9f5e401534989a97efe2e2704096bc2001377f15da56a37ac52d12b2dbebafb2'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'No dude en matricular con él, explica súper bien y al principio mete mucho miedo sobre el curso, pero realmente es necesario. Pareciera que es odioso, pero es una teja de persona y siempre esta dispuesto a ayudar. No califica tan duro los exámenes, las tareas son difíciles pero no imposibles'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'c79e38868e2f2f09b77d82cbdc89c6b60d326fb28e92b2d9cf5d1a851ceb8818'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profe del TEC. Este mae te va dejar las expectativas altas de lo que es ser un profe. Lleven con el cualquier mate si de verdad quieren adentrarse a entender y razonar. Llevaría con él los demás cursos de mate sin pensarlo. Deja porcentaje por asistir a clases y eso es un plus'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'bb6a00c88295234fa31a203792298443f9ce1a2696babe9cb8d8d84d5890a771'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El profe es top enseñando, no creo que haya nadie que explique tan bien como él. El profe ayuda mucho y es muy buena nota, las tareas son rudas pero se aprende un montón y los exámenes se hacen fáciles si hicieron bien las tareas, aparte deja videos los finde y hay que verlos para ir bien en clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Clases excelentes']::TEXT[], '2024-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'd2d578ddcd811a7ae25925c94d385d7ccf2f47deda150b2142d5469665ade9b9'::TEXT, ARRAY[1647]::BIGINT[]),
    (491::BIGINT, 'El profe es excelente, hace ejercicios difíciles pero bien explicados con lo cual se llega bien para los exámenes, su forma de explicar es distinta a los demás profes pero eso hace que se le ponga más atención, ayuda bastante y le importa mucho la reputación que tiene cómo profe.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-10-06T00:00:00+00:00'::TIMESTAMPTZ, '24310ca2d8b3671c3dd0e430dbbba274ae897ceee03d5ef5f2eed02305d1747f'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'No desaproveche lo oportunidad de matricular con este profe, es el mejor con creces. Hay un rubro por asistencia que son puntos prácticamente gratis, no hay quices solo tareas y son grupales'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'e42771af71c05a6b3c9624006d46d69d1c73ba39a439a91ddd166b83e36da4e7'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El profe es incre, explica muy muy bien. Prepara muy bien para pruebas. Deja videos semanales que sí o sí hay que ver para seguirle el ritmo. Ayuda bastante. En clase puede intimidar pero solo es de tirarse al agua y preguntar y atiende bien. Es muy militar, si es persona delicada mejor busque otro.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2024-09-04T00:00:00+00:00'::TIMESTAMPTZ, '8b0c1ec0c8a6846ab84ff59fddf611f1f07e49652411ca2fdf7695a947c02911'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profesor para llevar CDI, explica excelente tomando en cuenta que de por si calculo es un curso bastante difícil. Intente practicar bastante por su cuenta y acérquese al profesor cuando tenga dudas, de fijo le va a ayudar. Intente que le vaya bien en las tareas. Recomendado si viene de MG.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-09-04T00:00:00+00:00'::TIMESTAMPTZ, '8568881a1f79eff099676b2a5b39c0d9c138b6c95f3f23d6f3db346068ce4016'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Muy buen profesor, explica muy claro, las tareas son complicadas pero el profe siempre está atento a dudas y siempre se sacan adelante, da puntos extra y en si ayuda bastante, es de los mejores profes de mate.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'b1932085da4fc22a7c962d762cefa4d49e8955cc1d28bc4ee856eb5cff3a75cf'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es increíble explicando y da muchos ejemplos de los temas. Siempre está dispuesto a ayudar y valora mucho el esfuerzo que ponga en sus trabajos. Da porcentaje extra en tareas que salva un montón. Lo escogería otra vez sin dudarlo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '38bdb70eacac4f1f363542b494da327d92d2678e9f60008665059c64339a304d'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profe si uno quiere conseguir buenas bases en matemática, explica todo muy bien. Deja tareas grupales que pueden ser algo largas pero con un buen grupo se consiguen, no hace quizzes y da puntos extra en las tareas. 10% de la nota es asistencia.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b995936fc2aa7a9598c7635aaa0ee3cf017f98ce1c8270309cabd84fa192430f'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El profe está loco literal, hace algunos comentarios de humor negro, un poco autoritario, peeeeero la primera vez que le entiendo la materia a un profe de cálculo entonces di recomendado nada más tener cuidado de no caerle mal'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1015954de7afb4c386cbdb750bbb97f2c894004ff0b1ddd9b718552ab29c8e0f'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '9c61291558d2fc0d43721f0738fc17506be5ca9b6d6cf0e0159a7ca33e09fe6a'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El curso es díficil, entonces hay que ponerle desde el principio y el profe siempre está dispuesto a ayudar. En lo personal ha sido el mejor profesor que he tenido de mate, es cierto lo que dice de que todos son incompetentes a la par de él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f6a2161ace49d592dd69e5d63ab8287c09198993ba980ab1f3d8dfc4cd8b938b'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Excelente profe, es demasiado tuanis. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '931f73781ec6f0e2f6b773f16d828ad187771dbd906a451a0f44eb2c2c213c4b'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Si tiene la oportunidad de matricular con él hágalo, es un profesor que se preocupa más por el esfuerzo de los estudiantes que por el rendimiento en un examen, vaya a hora consulta y practique mucho. Sabe mucho y ama lo q hace, sáquele provecho a eso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '4a6aef0e48134fb64cb9519c9f2664fc7dc3ab4dc7745d63916ea995655ed816'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El profe sabe demasiado y como persona es buena nota, solo no hay que tomarse personal los comentarios. El curso es difícil por lo que si hay que ponerle desde un inicio, pero el profe siempre está dispuesto a atender dudas y procura que uno aprenda, además que da porcentaje extra en las tareas'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '85e42bab16cbd3907bb95cd05b4e24b3e15790d98e6bbbf6a3c67200967d12e7'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Sabe demasiado y explica super bien. El curso es muy difícil, hay que ponerle desde el inicio, pero él le sube porcentaje a las tareas, se full logra si practica bastante aunque ud no sea tan bueno en mate. Nada más no tomarse tan en serio sus comentarios, de verdad no es tan malo como parece.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e343f7bdf1f97df141ac1486c1fb66ad8703eb71d9c6df9bb170afcf99b015bc'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'la materia en si es muy ruda pero el profe explica super bien y trata de que las clases sean cómodas para el estudiante las tareas son muy difíciles es bueno buscar un buen grupo de trabajo. lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Inspirador']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5704f0d4f9ee3d7832b0f8b0fbf3f6e80028e7901a3f80a006009a256a603e05'::TEXT, ARRAY[1034]::BIGINT[]),
    (491::BIGINT, 'Explica muy bien y si usted va a consulta fijo le ayuda. Las clases no se hacen tan pesadas por que deja videos extra, aunque son un poco largos ayudan para que el profe no se salte temas o los explique muy rápido (que es lo que otros hacen). Si usted aprende rápido se lo recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b7c02d9ec8c722a529cdca3949fd7aedeec62dc13909b57b459806b28866f289'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'La clase es pesada y la da rápido, hay que estar atento. Explica bien y está disponible para atender consultas. Además deja tareas y exámenes con solucionario, lo que es muy útil para estudiar. El curso es complicado para los que tenemos muy malas bases en matemática, pero con esfuerzo se llega.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4eb03d92590c483bd81e73b2430e1f89d658b364c1b557db639fd55dacd34e2d'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El curso en sí es muy duro y hay que repasar todos los días, ocupa mucho tiempo. El profe explica SÚPER bien, siempre está dispuesto a recibir consultas. Las tareas son muy difíciles, largos y son grupales, consigan un buen grupo de trabajo! El profe da mucho % extra para ayudar. No duden, con él D1'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, '0cf6a716a7f086694e3525bc198beda4f2acafac29907fc07df6524d8d856d5a'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profe que he tenido, pasé por varios profes pues repetí mucho el curso. Y hasta ahora entendí y lo logré. Pone a trabajar bastante. Da crédito extra para aprovechar. No espere pasar fácil porque en general el curso ni es fácil. Es muy cómico en clase, no hay que tomarlo en serio.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'ad560a2a8dc652e52ef9555c69b0ffd653f2cf7381fdd6dd0cf71c71c4e0c9c6'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Si quieren entender matriculen con este profe. la clase no es aburrida e intenta ayudar cuando no se entendió algo. Sí es cierto que hace comentarios pesados y deja una cantidad de trabajo extra MUCHO mayor a los profes, pero eso ayuda entender. Prepárese para trabajar DEMASIADO y aprobar CDI!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'acbe74d83174703b9ce5eae3e2819fbae2ae6ecf987d554d9a0d4fe4303f9c1b'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profesor que existe de la cátedra, literalmente es el papá de los tomates, sus clases son super excelentes hace parecer fácil lo que es difícil, pero eso sí tiene que estar dispuesto a esforzarse al 100%, él valora mucho eso, súper recomendado!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'c7f19b3b4ef9573ca5397e31305e1c9797930e3628c7d0c1def0a0082ccd41ad'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Excelente profe, el hae su parte, explica todo de la manera mas ordenada y clara posible, revisa rapido y hace actividades de puntos extra durante le curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '2a2357f2f1f786a3244b8dfe6f07da18e1988ce5114d555bca8408605b0192eb'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Buen profe, explica muy bien y sabe enseñar, se ve que el mae sabe. Es cómico, deja credito extra y en general lo ayuda a uno si necesita puntos. Calculo es una materia complicada pero con el las posibilidades de pasar se incrementan. Volveria a llevar un curso con el. Super recomendado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'd797827c76eab7927e5503602ecc1b02bcf351af7abcad146bfbadb6da9c0458'::TEXT, ARRAY[1034]::BIGINT[]),
    (491::BIGINT, 'El profesor es muy bueno explicando. Si uno quiere pasar fácil no es el mejor, pero si quiere aprender sí es muy bueno. Deja tareas grupales a veces de viernes para domingo entonces puede quitarle tiempo del fin de semana, pero aparte de eso recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, '0b7a5450faaff220c3579f4ee436d8df90767af4266c0657a30cf5e1e70c9ee9'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '214d346875c557c06817947fc311d94ffd0fbae8d0958e869a1df2d2ead845c0'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'Es un excelente profesor, explica muy bien, pero evalúa a como explica, las tareas son pesadas pero logrables, las clases con él en general son muy entretenidas y da porcentaje por asistencia, 100% recomendado'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, '1ecdc8caf53cb31ce91cac6270979bfc64f65d02c16d0a6ad927bb43840e697b'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'Recomiendo mucho a este profesor, si usted muestra interés en clases y participa, siempre esta dispuesto a ayudar. Da clases muy completas, siempre deja claro de donde vienen las cosas y esto para mí es súper útil para después recordar los procedimientos. Lo volvería a llevar con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-24T00:00:00+00:00'::TIMESTAMPTZ, '8d69e23a5b23488fe3b016bc3531e7f31ce726679bdb4e7d22226fe8c8d8f454'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'De todos los cursos de matemáticas que he llevado, este ha sido el mejor profe, tiene una perspectiva distinta de la mate y así mismo lo demuestra en sus clases se nota que ama lo que hace, elcurso en sí fue difícil pero siempre estuvo para ayudar, como enseña evalúa (evalúa duro-explica excelente)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'a8555728de2af2607be7ca363959a131e21d309ac69f02b17c92701eedc1f400'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'Si quiere pasar fácilmente mejor busque otro profe. Las tareas son muy pesadas, con este profe tiene que ganarse curso, si lo recomiendo :)'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, '3c9708b2ed50d217761571d47714cca459422fb7f03695e98f532f9ed09fcdcf'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'Buen profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-14T00:00:00+00:00'::TIMESTAMPTZ, '642cbd4ef17d430c9dfbd07d46a10f0c1b81c1d16484f0634c80b0c89caa01f1'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Explica increíble. Da crédito extra si es necesario. Atento a ayudar. Sí hay que bretear mucho eso sí, ya que es muy exigente (pero para bien) y estricto. Sus tareas usualmente es en equipos, son largas y durillas. Depende mucho de qué tan bueno es su equipo. Vale mucho la pena el curso con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Da crédito extra']::TEXT[], '2024-01-12T00:00:00+00:00'::TIMESTAMPTZ, '85fbdce84038abcce0d4478142d3cb0b9c6aa4f5f30a517a59043c0468da31b4'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es muy bueno explicando, las tareas en grupo son bastante difíciles, y todo depende de su grupo de trabajo básicamente'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '6e0c020f7f5e2fcfc892d39387a00e4bedbc16095ff13356f48e43665498e053'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'Buen profesor, da crédito extra pero las tareas son bastantes pesadas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1f9f54d8c7b6304add3756e973ca1c42e0add54073b32271222806ca7673fba7'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El profe explica muy bien, pero se atrasa y se va por las ramas, en ocasiones se va más por la teoría que por la práctica. Da bastante crédito extra y no hace quices, pero sus tareas son demasiado largas y duras. Es una buena opción, pero si hay que ponerle mucho porque es muy estricto.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '36244fed3ef0d51958a988b986b3679f0f5c5979a43d0fabc0f5ea4873263aff'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mae es MUY bueno dando el curso, la cosa es que el curso es bien pesado así que es llevarlo al día SÍ o SÍ. El mae es estricto pero es muy comprensivo y da hasta crédito extra varias veces en el semestre pero sí hay que ganarselo. Si mete con él es porque usted es 0 vago y quiere aprender fuuuull'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2023-11-29T00:00:00+00:00'::TIMESTAMPTZ, '1947e4c4c57c302a214126cc6835e72aa362d20a6122f77749acaead5dbd9651'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Muy bien. Deja varias tareas en grupo. Explica muy bien y está atento a las consultas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Inspirador']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, '8b1192caba58ae6846b6ffa510eb3b5b99416e6e6bcbece942d362e2bc5de390'::TEXT, ARRAY[563]::BIGINT[]),
    (491::BIGINT, 'El profe es de lo mejor que he visto en la escuela de matemática. Repetí muchos cursos de mate y ví muchos profes y afirmo que es el único que vale la pena. Le apasiona la materia y eso contagia, ayuda un MONTON, si tien explicar un tema de 0 en la ofi lo hará, pero PONGALE, no le gusta los vagos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2023-09-11T00:00:00+00:00'::TIMESTAMPTZ, '27db5671b9b01cbb4392d00c4f13c7f6aee8ab406f8294c3815c6ec08ad9752c'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'El profe "es muy militar" pero en el buen sentido, le cuadra que le ponga literal desde semana 1. Explica claro e increible. El mae tiene autismo, no es malo, solo que se expresa sin filtro y la gente sensible se podría ofender o sentir mal, pero no lo hace con intención, solo es de dejarlo ser y ya'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2023-08-11T00:00:00+00:00'::TIMESTAMPTZ, '595e36cda480d2bc69d64a8798cbd1dac1947b2de4647dd6d83d253fbc06d7b4'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'De los mejores profes que he tenido, y he pasado como por 3. El mae fijo es autista porque tiene un humor peculiar podriamos decir. Siempre busca ayudarlo a uno pero si uno esta dispuesto a bretear BASTANTE.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Da crédito extra']::TEXT[], '2023-08-01T00:00:00+00:00'::TIMESTAMPTZ, '0bbecd6c9a23ccdb8e1f8cf9e599bf4d5567cc771bbd65395b9ac48a4202bba5'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Un gran profe la verdad, le más capacitado y conocedor que me ha tocado, el mae ayuda super bien si usted pregunta, consulta flexible y se queda después de la clase si usted le pide. Las tareas son lo más duro porque requiere mucho brete en poco tiempo pero no es nada de otro mundo ya quesongrupales'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f6e48c3cc3421adc44582965ebe949a42df967244dfa2b2538ac7817d9053ea4'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'El profe es matemático puro y en las tareas que él asigna es bastante exigente, pero nada que no se pueda hacer. A veces hace comentarios un poco fuera de lugar pero de igual manera explica bien, si usted le pone y va a consultas el profe de fijo le ayuda.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5c04e601e2b908d95056962622e9d4363c581f1a1f2bbe53facff45efef371a9'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Explica bastante bien, y si ve que usted le pone, le ayuda de fijo. Por otro lado, si ve que usted NO le pone, yo creo que más bien hace lo posible para quedarlo, entonces cuidado ahí. Este semestre metió un 10% de asistencia, pero quién sabe si seguirá haciendolo porque el pasado no.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '61e8d8ad30931e7a16483e0d94c537a959795ce4e3752e1d54cef7eb71bac01f'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'El profe es una teja, si usted es sencible (o feminista) no matricule con el, el mae se le caga a todo y todos (en el buen sentido, da gracia).Sin duda llevaria el curso con el, te califica muy duro, pero ayuda si ve que uno le pone, inclusive da puntos por orden y asistencia(10%).'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1bad93c63da2cdd726c42d4548914962fb7c44c4a91fa3ebc743a524ff4c8303'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Super recomendado, fue la segunda vez que llevaba el curso y me ayudó a pasar. Tiene un humor particular, exigente con la presentación de los trabajos, pero si muestra interés al curso al final del semestre le ayuda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b0eaca9f0980ed2a57ff2e74afe26cf2215ccb3b195f64e769a308c6d3fe3f7d'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Un excelente profesor, sin duda volvería a llevar un curso con él. Explica la materia un toque rápido, pero es por la cantidad de materia que hay en el curso. Las tareas son grandes, pero abordan bastante bien todo el contenido que se ve. Se nota que de verdad le interesa que el estudiante aprenda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '531df48772d0d13368138ef72959f2c962884faf593901bc53bab36307a3ae6f'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'El mejor profe que he tenido de mate, explica bastante bien y es muy agradable, se nota que quiere que el estudiante aprenda. Tareas largas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '502f1ed2168074d21b7dad971dd2a932efdded25176443ac64c22422b52ce0db'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'El mejor profe de mate que he tenido, explica bien, hace procedimientos, califica "duro" en los trabajos pero es lo necesario, le gusta ver que se esfuercen, si lo tiene de opción para llevar algún curso, no lo dude.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd345cc7fa9bd8401648589ae3d2040c2c0aaf74691591e77cfbeee1608339091'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es un excelente profesor. Tiene un humor particular pero es muy pura vida. Lo único de lo que me quejo es que va demasiado rápido, entonces usted o copia o presta atención porque no da chance de hacer ambas cosas. Si él ve que tiene interés en el curso le puede dar ayuda al final del semestre.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'f63eddb462e8a5b272058efa889178d72522ff65cf18da602ffc3d347bf4133f'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Excelente profesor. Explica la materia de una excelente manera, aborda algunos aspectos que puede que no se califiquen en el examen pero son demasiado útiles. Califica de una muy buena manera, si uno está al tanto de qué es lo que él quiere. Parece rudo pero él sabe lo que hace.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '45c3e0e84af280ffaff893e19448d086063bcc128344144038956f554cd4611c'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'De los mejores profes que he tenido. Me hubiera gustado llevar cursos anteriores con él. Si le pone lo ayuda pero si no tiene interés o va por obligación él lo notará y no le prestará cuidado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Da crédito extra']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, '2da4e71a35a3c31d855c38a45e89aebe93d594b315767d924abce7eb00e75184'::TEXT, ARRAY[935]::BIGINT[]),
    (491::BIGINT, 'Andy es excelente, es matemático, por lo que explica de donde vienen las cosas, lo cual ayuda a entender mejor los temas, siempre está atento a consultas. Lo recomiendo 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-05-25T00:00:00+00:00'::TIMESTAMPTZ, '30aefa971824561ac7d6af6bb2281ea4db4cafff592b40c39759ba19c4797b20'::TEXT, ARRAY[634]::BIGINT[]),
    (491::BIGINT, 'Un gran profesor, califica suave, explica muy bien y en general lo recomendaria mucho para CDI que fue con la que lleve con el.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-18T00:00:00+00:00'::TIMESTAMPTZ, '9b9ab586ccdedbee3844e40ee5a797484520a8c46bfa964ecae9d471b673fc46'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Nada malo que decir del profe, de los más buena gente que puede haber, el mae le va a ayudar si le pone ganas, pero demuestrele que tiene ganas de pasar el curso. Pregunte lo que quiera y aproveche horas de consulta, el mae le va a ayudar y los examenes se hacen super fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '6e7b984f3497e2b9bc47babc6e87c74b05d8ed6ddd9f9170e2c2f891815e1979'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es un excelente profesor, se le puede preguntar por lo que sea sin ningún miedo, regala bastantes puntos si fuera necesario. A veces hace comentarios algo inapropiados pero es en forma de humor y no son personales hacia nadie. La materia como tal no es fácil pero él explica bastante bien.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '7f985c7d2ad58f8ad6dbc15ff61045296366e211bc12858906a7fbd4ce4186e2'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Excelente profesor, no califica duro las tareas pero igual le importa la entrega de un trabajo bien elaborado. Las clases con un poco largas pero es porque hace bastantes ejercicios. Siempre graba las clases y generalmente hace un grupo de Telegram que sirve para atender dudas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-12T00:00:00+00:00'::TIMESTAMPTZ, '2d38f0757d2f2294480262cf289042b28cde519788f828bcbc8aea0ecb6dbd7b'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Es buena gente y comprensivo, eviten negociar trabajos en grupo, del todo no hace clases presenciales y a veces se confunde resolviendo sus propios ejercicios. Para pasar tiene que ir con catedra porque el video de la clase (asincrónica) no se entiende del todo'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-05T00:00:00+00:00'::TIMESTAMPTZ, '4b141cc806e92f5f02c8637569371df651388a4db3712ad2bee2322f583943de'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Las clases del profe son asincrónicas, así que sea organizado o se va a perder y va a ir atrasado con la cátedra. Explica lo suficientemente bien, pídale ayuda siempre que lo necesite porque es muy flexible con las horas de consulta. Para discreta es el más suave y más bueno que puede encontrar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'ee90e95b52186130349a25504fa1e8f4aab97d59811d4eedaa83e8a5b10e7cf0'::TEXT, ARRAY[1018]::BIGINT[]),
    (491::BIGINT, 'No deja nada de trabajos, explica súper claro y si uno le pide ayuda está dispuesto a hacer una reunión por zoom para explicar. Lo único que no me agradó fue que todas las clases son grabadas, sin embargo si uno es bien organizado no hay problemas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'e54952b6cc415ebe3e499c7c49d4e786df86ec7dd9bc5d2089fb49a58fbf7b69'::TEXT, ARRAY[1018]::BIGINT[]),
    (491::BIGINT, 'Es un excelente profesor. Brinda mucho apoyo, aclara dudas y lleva todo al día. A veces se adelanta un poquito, pero pura vida, pues eso se da en las grabaciones y en general es bueno. Además, convierte temas complejos en fáciles, más fáciles que los videos del TEC.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '88b3dbceea040d68a406d1cd2784eb02728b93152530c89079b6bf389cb61a54'::TEXT, ARRAY[605]::BIGINT[]),
    (491::BIGINT, 'Da ejemplos de la vida cotidiana, y la parte teórica en general de la materia te queda claro, es un profe un toque vago, pero si usted le pone el mae le ayuda en todo lo que nesesites, es muy llevadero, siendo que es profesor muy apegado a la virtualidad, pero si usted le pone le sirve y pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '16a8e58b5b900e37e75ca791d9ccbf8976b83892af606acd9d559bffa67ab2cc'::TEXT, ARRAY[1018]::BIGINT[]),
    (491::BIGINT, 'Trabajos mínimos y sencillos; sin embargo temas complejos y los quices se pueden complicar si no se practica , ni se lleva la materia al día.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'e4391b4ea20596ce88933ab6a842d6f5cfa3086ab60ed82d73e34c086b880603'::TEXT, ARRAY[1018]::BIGINT[]),
    (491::BIGINT, 'Para virtualidad mate discreta es muy difícil puesto que la forma de aprendizaje son con material que deja la cátedra, que es demasiado, por eso el profe no puede desarrollar mucho las clases más que con ejemplos larguísimos. Por otra parte el profe no se complica con trabajos ni nada.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '1699a1074e14b85f14165bc3c498db0e901fd0972a31caf967477bcef8395fe6'::TEXT, ARRAY[1018]::BIGINT[]),
    (491::BIGINT, 'Como otros profes de mate, graban las clases y luego hacen una clase sincrónica de repaso. Explica super claro, aunque a veces se hace bolas, pero se le entiende todo. No jode con trabajos ni nada de eso, sólo dejo de proyecto una bitácora toda ez. Siempre está dispuesto a conectarse para ayudarle'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '397c13d695f33030327bc2c92fd7303fc389bfc24350417f9e6200bc3ab35890'::TEXT, ARRAY[1018]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
